<?php if($editorialExtras['evidence']):?><section class="editorial-evidence" aria-labelledby="public-evidence-heading"><span class="eyebrow">What supports this account</span><h2 id="public-evidence-heading">Evidence and limitations.</h2><div class="editorial-evidence-grid"><?php foreach($editorialExtras['evidence'] as $card):?><article class="editorial-evidence-card"><span class="eyebrow"><?=e(editorial_evidence_bases()[$card['basis']]??'Evidence')?></span><h3><?=e($card['label'])?></h3><p><?=nl2br(e($card['summary']))?></p><?php if($card['observed_on']):?><p class="editorial-muted">Observed <?=e(format_date($card['observed_on']))?></p><?php endif;?><?php if($card['limitations']):?><p><strong>Limitations:</strong> <?=nl2br(e($card['limitations']))?></p><?php endif;?><?php if($card['url']):?><a class="text-link" href="<?=e($card['url'])?>" rel="noopener noreferrer">Open public source ↗</a><?php endif;?></article><?php endforeach;?></div></section><?php endif;?>
<?php if($editorialExtras['updates']):?><section class="editorial-updates" aria-labelledby="editorial-updates-heading"><h2 id="editorial-updates-heading">Updates and corrections.</h2><ol><?php foreach($editorialExtras['updates'] as $update):?><li><strong><?=$update['update_kind']==='correction'?'Correction':'Meaningful update'?></strong> · <time datetime="<?=e(date(DATE_ATOM,strtotime($update['published_at'])))?>"><?=e(date('j M Y, H:i T',strtotime($update['published_at'])))?></time><p><?=nl2br(e($update['note']))?></p></li><?php endforeach;?></ol></section><?php endif;?>
